style.css:
@-moz-document url-prefix("https://learn3.k12.com/calendar") {
/* Background image */
  body, html {
    background: url("https://cdn.jdpower.com/What%20Is%20A%20JDM%20Car.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Make main panels transparent */
  #app, 
  .calendar-container, 
  .calendar, 
  .fc-view-container, 
  .fc-view,
  .fc-scroller,
  .main-content, 
  .content, 
  .container {
    background: rgba(0,0,0,0.4) !important; /* transparent dark overlay */
    backdrop-filter: blur(6px) !important;   /* adds a nice glass effect */
    border: none !important;
    box-shadow: none !important;
  }

  /* Transparent headers and toolbars */
  .fc-toolbar, 
  .fc-header-toolbar {
    background: rgba(0,0,0,0.3) !important;
    backdrop-filter: blur(4px) !important;
  }

  /* Calendar cells transparent */
  .fc-day, 
  .fc-day-top, 
  .fc-widget-content, 
  .fc-widget-header {
    background: transparent !important;
  }

  /* Event text contrast */
  .fc-event {
    background: rgba(255,255,255,0.2) !important;
    color: #fff !important;
    border: 1px solid rgba(255,255,255,0.3) !important;
  }

  /* Buttons */
  .fc-toolbar button {
    background: rgba(255,255,255,0.15) !important;
    color: #fff !important;
    border: 1px solid rgba(255,255,255,0.3) !important;
  }
  .fc-toolbar button:hover {
    background: rgba(255,255,255,0.3) !important;
  }
}
